    if (iconImages[type]) continue;
    const img = new Image();
    img.onload = () => onReady?.();
    img.onerror = () => onReady?.();
    const hrefMatch = svg.match(/<image[^>]*href="([^"]+)"/);
    img.src = hrefMatch ? hrefMatch[1] : "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
